create or replace function public.notify_support_ticket() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_op='INSERT' then perform public.emit_notification(p.id,'support','Novo chamado','Há um novo chamado de suporte.','support',new.id,'support:admin:'||new.id) from public.profiles p where p.role='admin' and p.status='active'; elsif tg_op='UPDATE' and new.updated_at is distinct from old.updated_at then perform public.emit_notification(new.seller_id,'support','Resposta do suporte','Seu chamado "'||new.subject||'" recebeu uma atualização.','support',new.id,'support:update:'||new.id||':'||floor(extract(epoch from new.updated_at)*1000)::bigint); end if; return new; exception when others then return new; end $$;